    $html.='<video controls src="'.$esc($video['url']).'" poster="'.$esc($images[0]['url']).'"></video>';
    foreach($audio as$index=>$a){$url=$esc($a['url']);$html.=$index%2===0?'<audio controls src="'.$url.'"></audio>':'<audio controls><source src="'.$url.'"></audio>';}
    return $html;
