            if($app==='adminapi'){$site='http://audit-app:8000';$thumb=strpos($row['satt_dir'],$site)!==false||strstr($row['satt_dir'],'http')!==false?$row['satt_dir']:$site.$row['satt_dir'];$original=strpos($row['att_dir'],$site)!==false||strstr($row['att_dir'],'http')!==false?$thumb:$site.$row['att_dir'];
                m86_expect($dto['att_dir']===$original&&$dto['satt_dir']===$thumb&&is_string($dto['time'])&&preg_match('/\A\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2}\z/D',$dto['time'])===1,'REAL_VIDEO_SELECTOR_ORIGINAL_PLATFORM_URL_TIME_BRANCH');}
